package com.bank.pattern;

import java.util.Objects;
import java.util.logging.Logger;

// Detects whether a pattern tree appears as a subtree of the hierarchy.
public class PatternMatchService {

    private static final Logger log = Logger.getLogger(PatternMatchService.class.getName());

    public boolean isSubtree(RoleNode root, RoleNode pattern) {
        if (pattern == null) {
            return true; // empty pattern matches anywhere
        }
        if (root == null) {
            return false; // no tree left to search
        }
        // Does the pattern match exactly rooted here?
        if (isSameTree(root, pattern)) {
            return true;
        }
        // Otherwise search both children.
        return isSubtree(root.getLeft(), pattern)
                || isSubtree(root.getRight(), pattern);
    }

    // Strict structural + value equality.
    private boolean isSameTree(RoleNode a, RoleNode b) {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        if (!Objects.equals(a.getRole(), b.getRole())) return false;
        return isSameTree(a.getLeft(), b.getLeft())
                && isSameTree(a.getRight(), b.getRight());
    }

    public boolean detectPattern(RoleNode hierarchy, RoleNode pattern) {
        boolean found = isSubtree(hierarchy, pattern);
        if (found) {
            log.severe("Fraud pattern DETECTED as a subtree — investigate");
        } else {
            log.info("Fraud pattern not present in this hierarchy");
        }
        return found;
    }
}
