package com.bank.pattern;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class SubtreeDemo {

    private static final Logger log = Logger.getLogger(SubtreeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Fraud Pattern Subtree Detection");

        //  Hierarchy:        Manager
        //                   /        \
        //             CreditOfficer  RiskHead
        //               /      \
        //            Clerk    Verifier
        RoleNode hierarchy = new RoleNode("Manager");
        RoleNode credit = new RoleNode("CreditOfficer");
        hierarchy.setLeft(credit);
        hierarchy.setRight(new RoleNode("RiskHead"));
        credit.setLeft(new RoleNode("Clerk"));
        credit.setRight(new RoleNode("Verifier"));

        // Present pattern: CreditOfficer -> (Clerk, Verifier)
        RoleNode present = new RoleNode("CreditOfficer");
        present.setLeft(new RoleNode("Clerk"));
        present.setRight(new RoleNode("Verifier"));

        // Absent pattern: CreditOfficer -> (Clerk, Auditor)
        RoleNode absent = new RoleNode("CreditOfficer");
        absent.setLeft(new RoleNode("Clerk"));
        absent.setRight(new RoleNode("Auditor"));

        PatternMatchService service = new PatternMatchService();
        service.detectPattern(hierarchy, present); // DETECTED
        service.detectPattern(hierarchy, absent);  // not present
    }
}
